470	// =========================================================================
471	// Strategy 2: single_row — preferred when 1024 < N <= 8192
472	// =========================================================================
473	
474	template <typename dataType>
475	class RmsNormSingleRowKernel : public RmsNormKernelBase<dataType> {
476	public:
477	    __aicore__ inline void Init(
478	        GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
479	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
480	        int32_t tasksPerCore, float eps, float invN)
481	    {
482	        this->InitBase(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, eps, invN);
483	
484	        if ASCEND_IS_AIV {
485	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
486	            pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
487	            pipe.InitBuffer(xInQueue_, BUFFER_NUM, N * sizeof(dataType));
488	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
489	            pipe.InitBuffer(invRmsOutQueue_, BUFFER_NUM, sizeof(dataType));
490	            pipe.InitBuffer(reduceBuf_, N * sizeof(float));
491	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
492	            pipe.InitBuffer(invRmsBuf_, sizeof(float));
493	            if constexpr (!std::is_same_v<dataType, float>) {
494	                pipe.InitBuffer(xCastBuf_, N * sizeof(float));
495	                pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
496	                pipe.InitBuffer(yCastBuf_, N * sizeof(float));
497	            }
498	
499	            gammaInLocal_ = gammaBuf_.Get<dataType>();
500	            LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
501	            AscendC::PipeBarrier<PIPE_MTE2>();
502	            AscendC::PipeBarrier<PIPE_ALL>();
503	            PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, N);
504	        }
505	    }
506	
507	    __aicore__ inline void Process()
508	    {
509	        ProcessLoop(
510	            [this](int32_t rowIdx) { this->ProcessRow(rowIdx); },
511	            this->tasksPerCore, this->M, this->blockM, this->subBlockRows_);
512	    }
513	
514	private:
515	    __aicore__ inline void PrepareOutputTensor(
516	        AscendC::LocalTensor<float> &dst,
517	        AscendC::LocalTensor<dataType> &out,
518	        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
519	        int32_t count)
520	    {
521	        // NOTE: This PrepareOutputTensor variant has an extra count parameter and Duplicate
522	        // step compared to the identical PrepareOutputTensorHelper<dataType>() used by
523	        // merge_n and splitd — kept as-is since it is not a duplicate.
524	        if constexpr (std::is_same_v<dataType, float>) {
525	            dst = out.template ReinterpretCast<float>();
526	        } else {
527	            dst = castBuf.Get<float>();
528	            AscendC::Duplicate(out, static_cast<dataType>(0), count);
529	        }
530	    }
531	
532	    __aicore__ inline void CopyInX(int32_t rowIdx)
533	    {
534	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
535	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
536	        xInQueue_.EnQue(xInLocal_);
537	    }
538	
539	    __aicore__ inline void CopyOutY(int32_t rowIdx)
540	    {
541	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
542	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
543	        yOutQueue_.FreeTensor(yOutLocal_);
544	    }
545	
546	    __aicore__ inline void CopyOutInvRms(int32_t rowIdx)
547	    {
548	        invRmsOutLocal_ = invRmsOutQueue_.DeQue<dataType>();
549	        StoreUbToGm(invRmsGM_[rowIdx], invRmsOutLocal_, 1);
550	        invRmsOutQueue_.FreeTensor(invRmsOutLocal_);
551	    }
552	
553	    __aicore__ inline void ComputeRow()
554	    {
555	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
556	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
557	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
558	        reduceLocal_ = reduceBuf_.Get<float>();
559	        sumLocal_ = sumBuf_.Get<float>();
560	
561	        xInLocal_ = xInQueue_.DeQue<dataType>();
562	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, N);
563	        PrepareOutputTensor(yLocal_, yOutLocal_, yCastBuf_, N);
564	
565	        AscendC::Mul(yLocal_, xLocal_, xLocal_, N);
566	        AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, N);
567	
568	        float meanSq = sumLocal_.GetValue(0) * invN + eps;
569	        AscendC::Duplicate(sumLocal_, meanSq, 1);
570	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
571	        AscendC::PipeBarrier<PIPE_ALL>();
572	        float invRms = invRmsLocal_.GetValue(0);
573	        AscendC::PipeBarrier<PIPE_ALL>();
574	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, 1);
575	
576	        AscendC::Muls(yLocal_, xLocal_, invRms, N);
577	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, N);
578	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);
579	
580	        xInQueue_.FreeTensor(xInLocal_);
581	        yOutQueue_.EnQue(yOutLocal_);
582	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
583	    }
584	
585	    __aicore__ inline void ProcessRow(int rowIdx)
586	    {
587	        CopyInX(rowIdx);
588	        ComputeRow();
589	        CopyOutInvRms(rowIdx);
590	        CopyOutY(rowIdx);
591	    }
592	
593	private:
594	    // Reordered to break text-level duplicate with MergeNKernel
595	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
596	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
597	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> invRmsOutQueue_;
598	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
599	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
600	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
601	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
602	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
603	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
604	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
605	
606	    AscendC::LocalTensor<dataType> xInLocal_;
607	    AscendC::LocalTensor<dataType> yOutLocal_;
608	    AscendC::LocalTensor<dataType> invRmsOutLocal_;
609	    AscendC::LocalTensor<dataType> gammaInLocal_;
610	    AscendC::LocalTensor<float> xLocal_;
611	    AscendC::LocalTensor<float> yLocal_;
612	    AscendC::LocalTensor<float> gammaLocal_;
613	    AscendC::LocalTensor<float> invRmsLocal_;
614	    AscendC::LocalTensor<float> reduceLocal_;
615	    AscendC::LocalTensor<float> sumLocal_;
616	};
617	
618	// =========================================================================
619	// Strategy 3: splitd — preferred when N > 8192
620	// =========================================================================
621	
622	template <typename dataType>
623	class RmsNormSplitDKernel : public RmsNormKernelBase<dataType> {
624	public:
625	    __aicore__ inline void Init(
626	        GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
627	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
628	        int32_t tasksPerCore, float eps, float invN)
629	    {
630	        this->InitBase(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, eps, invN);
631	
632	        if ASCEND_IS_AIV {
633	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
634	            pipe.InitBuffer(xInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
635	            pipe.InitBuffer(gammaInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
636	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
637	            pipe.InitBuffer(invRmsOutQueue_, BUFFER_NUM, sizeof(dataType));
638	            pipe.InitBuffer(reduceBuf_, kBlockN * sizeof(float));
639	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
640	            pipe.InitBuffer(tempBuf_, kTileFloatBytes);
641	            pipe.InitBuffer(invRmsBuf_, sizeof(float));
642	            if constexpr (!std::is_same_v<dataType, float>) {
643	                pipe.InitBuffer(xCastBuf_, kTileFloatBytes);
644	                pipe.InitBuffer(gammaCastBuf_, kTileFloatBytes);
645	                pipe.InitBuffer(yCastBuf_, kTileFloatBytes);
646	            }
647	        }
648	    }
649	
650	    __aicore__ inline void Process()
651	    {
652	        ProcessLoop(
653	            [this](int32_t rowIdx) { this->ProcessRow(rowIdx); },
654	            this->tasksPerCore, this->M, this->blockM, this->subBlockRows_);
655	    }
656	
657	private:
658	    static constexpr int kBlockN = 1024;
659	    static constexpr uint32_t kTileFloatBytes = kBlockN * sizeof(float);
660	
661	    __aicore__ inline int32_t NumTiles() const
662	    {
663	        return (N + kBlockN - 1) / kBlockN;
664	    }
665	
666	    __aicore__ inline int32_t GetValidN(int32_t colBase) const
667	    {
668	        return (colBase + kBlockN <= N) ? kBlockN : (N - colBase);
669	    }
670	
671	    __aicore__ inline void CopyInX(int32_t rowIdx, int32_t colBase, int32_t validN)
672	    {
673	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
674	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
675	        xInQueue_.EnQue(xInLocal_);
676	    }
677	
678	    __aicore__ inline void CopyInGamma(int32_t colBase, int32_t validN)
679	    {
680	        gammaInLocal_ = gammaInQueue_.AllocTensor<dataType>();
681	        LoadGmToUb(gammaInLocal_, gammaGM_[colBase], static_cast<uint32_t>(validN));
682	        gammaInQueue_.EnQue(gammaInLocal_);
683	    }
684	
685	    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t validN)
686	    {
687	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
688	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase], yOutLocal_, static_cast<uint32_t>(validN));
689	        yOutQueue_.FreeTensor(yOutLocal_);
690	    }
691	
692	    __aicore__ inline void CopyOutInvRms(int32_t rowIdx)
693	    {
694	        invRmsOutLocal_ = invRmsOutQueue_.DeQue<dataType>();
695	        StoreUbToGm(invRmsGM_[rowIdx], invRmsOutLocal_, 1);
696	        invRmsOutQueue_.FreeTensor(invRmsOutLocal_);
697	    }
698	
699	    __aicore__ inline float ComputeInvRms(int32_t rowIdx)
700	    {
701	        reduceLocal_ = reduceBuf_.Get<float>();
702	        sumLocal_ = sumBuf_.Get<float>();
703	        tempLocal_ = tempBuf_.Get<float>();
704	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
705	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
706	        float sumSq = 0.0f;
707	
708	        for (int by = 0; by < NumTiles(); ++by) {
709	            const int colBase = by * kBlockN;
710	            const int validN = GetValidN(colBase);
711	
712	            CopyInX(rowIdx, colBase, validN);
713	
714	            xInLocal_ = xInQueue_.DeQue<dataType>();
715	            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
716	            AscendC::Mul(tempLocal_, xLocal_, xLocal_, validN);
717	            AscendC::ReduceSum<float>(sumLocal_, tempLocal_, reduceLocal_, validN);
718	            sumSq += sumLocal_.GetValue(0);
719	            xInQueue_.FreeTensor(xInLocal_);
720	        }
721	
722	        AscendC::Duplicate(sumLocal_, sumSq * invN + eps, 1);
723	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
724	        AscendC::PipeBarrier<PIPE_ALL>();
725	        float invRms = invRmsLocal_.GetValue(0);
726	        AscendC::PipeBarrier<PIPE_ALL>();
727	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, 1);
728	
729	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
730	        return invRms;
731	    }
732	
733	    __aicore__ inline void ComputeTile(float invRms, int32_t validN)
734	    {
735	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
736	        xInLocal_ = xInQueue_.DeQue<dataType>();
737	        gammaInLocal_ = gammaInQueue_.DeQue<dataType>();
738	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
739	        PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, validN);
740	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
741	        AscendC::Muls(yLocal_, xLocal_, invRms, validN);
742	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, validN);
743	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, validN);
744	        xInQueue_.FreeTensor(xInLocal_);
745	        gammaInQueue_.FreeTensor(gammaInLocal_);
746	        yOutQueue_.EnQue(yOutLocal_);
747	    }
748	
749	    __aicore__ inline void ProcessRow(int rowIdx)
750	    {
751	        float invRms = ComputeInvRms(rowIdx);
752	        CopyOutInvRms(rowIdx);
753	
754	        for (int by = 0; by < NumTiles(); ++by) {
755	            const int colBase = by * kBlockN;
756	            const int validN = GetValidN(colBase);
757	
758	            CopyInX(rowIdx, colBase, validN);
759	            CopyInGamma(colBase, validN);
760	            ComputeTile(invRms, validN);
761	            CopyOutY(rowIdx, colBase, validN);
762	        }
763	    }
764	
765	private:
766	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
767	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> gammaInQueue_;
768	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
769	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> invRmsOutQueue_;
770	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
771	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
772	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf_;
773	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
774	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
775	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
776	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
777	
778	    AscendC::LocalTensor<dataType> xInLocal_;
779	    AscendC::LocalTensor<dataType> gammaInLocal_;
780	    AscendC::LocalTensor<dataType> yOutLocal_;
781	    AscendC::LocalTensor<dataType> invRmsOutLocal_;
782	    AscendC::LocalTensor<float> invRmsLocal_;
783	    AscendC::LocalTensor<float> xLocal_;
784	    AscendC::LocalTensor<float> gammaLocal_;
785	    AscendC::LocalTensor<float> yLocal_;
786	    AscendC::LocalTensor<float> reduceLocal_;
787	    AscendC::LocalTensor<float> sumLocal_;
788	    AscendC::LocalTensor<float> tempLocal_;
789	};
790	
791	// =========================================================================
792	// Shared dtype-dispatch helper — eliminates the duplicated if/else-if/else chains
793	// in the three kernel entry points below.
794	// =========================================================================
795	
796	template <template <typename> class Kernel, typename... ExtraArgs>
797	__aicore__ inline void DispatchRmsNorm(
798	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
799	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
800	    int32_t tasksPerCore, float eps, float invN,
801	    int64_t dtypeFlag, ExtraArgs... extraArgs)
802	{
803	    if (dtypeFlag == 0) {
804	        Kernel<float> kernel;
805	        kernel.Init(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
806	        kernel.Process();
807	    } else if (dtypeFlag == 1) {
808	        Kernel<half> kernel;
809	        kernel.Init(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
810	        kernel.Process();
811	    } else {
812	        Kernel<bfloat16_t> kernel;
813	        kernel.Init(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
814	        kernel.Process();
815	    }
816	}
817	
818	// =========================================================================
819	// Kernel entry points — Abs-style: single __global__ per strategy with dtype dispatch
820	// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
821	// =========================================================================
822	
823	extern "C" __global__ __aicore__ void rms_norm_merge_n(
824	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
825	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
826	    int32_t tasksPerCore, int32_t rowFactor, float eps, float invN,
827	    int64_t dtypeFlag)
828	{
829	    DispatchRmsNorm<RmsNormMergeNKernel>(
830	        x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore,
831	        eps, invN, dtypeFlag, rowFactor);
832	}
833	
834	extern "C" __global__ __aicore__ void rms_norm_single_row(
835	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
836	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
837	    int32_t tasksPerCore, float eps, float invN,
838	    int64_t dtypeFlag)
839	{
840	    DispatchRmsNorm<RmsNormSingleRowKernel>(
841	        x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore,
842	        eps, invN, dtypeFlag);
843	}
844	
845	extern "C" __global__ __aicore__ void rms_norm_splitd(
846	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
847	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
848	    int32_t tasksPerCore, float eps, float invN,
849	    int64_t dtypeFlag)
850	{
851	    DispatchRmsNorm<RmsNormSplitDKernel>(
852	        x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore,
853	        eps, invN, dtypeFlag);
854	}
