// AscendC Sum kernel — strategies: merge_n, single_line, split_line
// Supports float32, float16, bfloat16
// Reduces along the last dimension: (outer_total, red_size) → (outer_total,)

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

__aicore__ inline int32_t BlockCountHelper(int32_t M, int32_t blockM)
{
    if (blockM == 0) { return 0; }
    return (M + blockM - 1) / blockM;
}

template <typename T>
__aicore__ inline void PrepareInputTensorHelper(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void PrepareOutputTensorHelper(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &out,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = out.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
    }
}

template <typename T>
__aicore__ inline void FinalizeOutputTensorHelper(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// Strategy 1: merge_n — preferred when red_size <= 1024
// =========================================================================

template <typename dataType>
class SumMergeNKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t outerTotal, int32_t redSize, int32_t blockLines,
        int32_t usedCoreNum, int32_t tasksPerCore, int32_t rowFactor)
    {
        this->outerTotal = outerTotal;
        this->redSize = redSize;
        this->blockLines = blockLines;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->rowFactor = rowFactor;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x),
                             static_cast<uint64_t>(outerTotal) * redSize);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), outerTotal);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockLines_ = blockLines / AscendC::GetSubBlockNum();
        rowLoops_ = subBlockLines_ / rowFactor;

        pipe.InitBuffer(xInQueue_, BUFFER_NUM, kMergeRowFactor * redSize * sizeof(dataType));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kMergeRowFactor * sizeof(dataType));
        pipe.InitBuffer(reduceBuf_, 2 * kMergeRowFactor * redSize * sizeof(uint8_t));
        pipe.InitBuffer(sumBuf_, kMergeRowFactor * sizeof(float));
        pipe.InitBuffer(sumCastBuf_, kMergeRowFactor * sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_, kMergeRowFactor * redSize * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= BlockCountHelper(outerTotal, blockLines)) {
                    continue;
                }

                for (int r = 0; r < rowLoops_; ++r) {
                    const int lineBase = bx * blockLines + subBlockIdx * subBlockLines_ + r * rowFactor;
                    const int validLines = outerTotal - lineBase;
                    if (validLines > 0) {
                        const int rows = (validLines >= kMergeRowFactor) ? kMergeRowFactor : validLines;
                        ProcessRows(lineBase, rows);
                    }
                }
            }
        }
    }

private:
    static constexpr int kMergeRowFactor = 8;

    __aicore__ inline void CopyInX(int32_t lineBase, int32_t rows)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(lineBase) * redSize],
                   static_cast<uint32_t>(rows * redSize));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t lineBase, int32_t rows)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[lineBase], yOutLocal_, static_cast<uint32_t>(rows));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void ComputeRows(int32_t rows, int32_t tileSize)
    {
        const uint32_t reduceShape[2] = {
            static_cast<uint32_t>(rows),
            static_cast<uint32_t>(redSize),
        };

        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
        sumLocal_ = sumBuf_.Get<float>();
        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, sumCastBuf_);

        xInLocal_ = xInQueue_.DeQue<dataType>();
        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, tileSize);

        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
            sumLocal_, xLocal_, reduceTmpLocal_, reduceShape, true);

        FinalizeOutputTensorHelper<dataType>(yOutLocal_, sumLocal_, rows);

        xInQueue_.FreeTensor(xInLocal_);
        yOutQueue_.EnQue(yOutLocal_);
    }

    __aicore__ inline void ProcessSingleRow(int32_t rowIdx)
    {
        const uint32_t reduceShape[2] = {1U, static_cast<uint32_t>(redSize)};

        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
        sumLocal_ = sumBuf_.Get<float>();
        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, sumCastBuf_);

        xInLocal_ = xInQueue_.DeQue<dataType>();
        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, redSize);

        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
            sumLocal_, xLocal_, reduceTmpLocal_, reduceShape, true);

        FinalizeOutputTensorHelper<dataType>(yOutLocal_, sumLocal_, 1);

        xInQueue_.FreeTensor(xInLocal_);
        yOutQueue_.EnQue(yOutLocal_);
        CopyOutY(rowIdx, 1);
    }

    __aicore__ inline void ProcessRows(int32_t lineBase, int32_t rows)
    {
        if (rows < kMergeRowFactor) {
            for (int r = 0; r < rows; ++r) {
                CopyInX(lineBase + r, 1);
                ProcessSingleRow(lineBase + r);
            }
            return;
        }

        const int tileSize = kMergeRowFactor * redSize;
        CopyInX(lineBase, kMergeRowFactor);
        ComputeRows(kMergeRowFactor, tileSize);
        CopyOutY(lineBase, kMergeRowFactor);
    }

private:
    int32_t outerTotal = 0;
    int32_t redSize = 0;
    int32_t blockLines = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int32_t rowFactor = 0;
    int subBlockLines_ = 0;
    int rowLoops_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> yLocal_;
    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
    AscendC::LocalTensor<float> sumLocal_;
};

// =========================================================================
// Strategy 2: single_line — preferred when 1024 < red_size <= 8192
// =========================================================================

template <typename dataType>
class SumSingleLineKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t outerTotal, int32_t redSize, int32_t blockLines,
        int32_t usedCoreNum, int32_t tasksPerCore)
    {
        this->outerTotal = outerTotal;
        this->redSize = redSize;
        this->blockLines = blockLines;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x),
                             static_cast<uint64_t>(outerTotal) * redSize);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), outerTotal);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockLines_ = blockLines / AscendC::GetSubBlockNum();

        pipe.InitBuffer(xInQueue_, BUFFER_NUM, redSize * sizeof(dataType));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, sizeof(dataType));
        pipe.InitBuffer(reduceBuf_, 2 * redSize * sizeof(uint8_t));
        pipe.InitBuffer(sumBuf_, sizeof(float));
        pipe.InitBuffer(sumCastBuf_, sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_, redSize * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= BlockCountHelper(outerTotal, blockLines)) {
                    continue;
                }

                for (int line = 0; line < subBlockLines_; ++line) {
                    const int lineIdx = bx * blockLines + subBlockIdx * subBlockLines_ + line;
                    if (lineIdx < outerTotal) {
                        ProcessRow(lineIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void CopyInX(int32_t lineIdx)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(lineIdx) * redSize],
                   static_cast<uint32_t>(redSize));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t lineIdx)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[lineIdx], yOutLocal_, 1);
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void ComputeRow()
    {
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
        sumLocal_ = sumBuf_.Get<float>();
        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, sumCastBuf_);

        xInLocal_ = xInQueue_.DeQue<dataType>();
        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, redSize);

        AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceTmpLocal_, redSize);

        FinalizeOutputTensorHelper<dataType>(yOutLocal_, sumLocal_, 1);

        xInQueue_.FreeTensor(xInLocal_);
        yOutQueue_.EnQue(yOutLocal_);
    }

    __aicore__ inline void ProcessRow(int32_t lineIdx)
    {
        CopyInX(lineIdx);
        ComputeRow();
        CopyOutY(lineIdx);
    }

private:
    int32_t outerTotal = 0;
    int32_t redSize = 0;
    int32_t blockLines = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int subBlockLines_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> yLocal_;
    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
    AscendC::LocalTensor<float> sumLocal_;
};

// =========================================================================
// Strategy 3: split_line — preferred when red_size > 8192
// =========================================================================

template <typename dataType>
class SumSplitLineKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t outerTotal, int32_t redSize, int32_t blockLines,
        int32_t usedCoreNum, int32_t tasksPerCore)
    {
        this->outerTotal = outerTotal;
        this->redSize = redSize;
        this->blockLines = blockLines;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x),
                             static_cast<uint64_t>(outerTotal) * redSize);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), outerTotal);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockLines_ = blockLines / AscendC::GetSubBlockNum();

        pipe.InitBuffer(xInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, sizeof(dataType));
        pipe.InitBuffer(reduceBuf_, 2 * kBlockN * sizeof(uint8_t));
        pipe.InitBuffer(accBuf_, sizeof(float));
        pipe.InitBuffer(sumBuf_, sizeof(float));
        pipe.InitBuffer(sumCastBuf_, sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_, kBlockN * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= BlockCountHelper(outerTotal, blockLines)) {
                    continue;
                }

                for (int line = 0; line < subBlockLines_; ++line) {
                    const int lineIdx = bx * blockLines + subBlockIdx * subBlockLines_ + line;
                    if (lineIdx < outerTotal) {
                        ProcessRow(lineIdx);
                    }
                }
            }
        }
    }

private:
    static constexpr int kBlockN = 1024;

    __aicore__ inline int32_t NumTiles() const
    {
        return (redSize + kBlockN - 1) / kBlockN;
    }

    __aicore__ inline int32_t GetValidN(int32_t colBase) const
    {
        return (colBase + kBlockN <= redSize) ? kBlockN : (redSize - colBase);
    }

    __aicore__ inline void CopyInX(int32_t lineIdx, int32_t colBase, int32_t validN)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_,
                   xGM_[static_cast<uint64_t>(lineIdx) * redSize + colBase],
                   static_cast<uint32_t>(validN));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t lineIdx)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[lineIdx], yOutLocal_, 1);
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void ProcessRow(int32_t lineIdx)
    {
        float total = 0.0f;

        for (int by = 0; by < NumTiles(); ++by) {
            const int colBase = by * kBlockN;
            const int validN = GetValidN(colBase);

            CopyInX(lineIdx, colBase, validN);

            reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
            sumLocal_ = sumBuf_.Get<float>();

            xInLocal_ = xInQueue_.DeQue<dataType>();
            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);

            AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceTmpLocal_, validN);
            total += sumLocal_.GetValue(0);

            xInQueue_.FreeTensor(xInLocal_);
        }

        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        accLocal_ = accBuf_.Get<float>();
        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, sumCastBuf_);

        AscendC::Duplicate(accLocal_, total, 1);
        FinalizeOutputTensorHelper<dataType>(yOutLocal_, accLocal_, 1);

        yOutQueue_.EnQue(yOutLocal_);
        CopyOutY(lineIdx);
    }

private:
    int32_t outerTotal = 0;
    int32_t redSize = 0;
    int32_t blockLines = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int subBlockLines_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> yLocal_;
    AscendC::LocalTensor<float> accLocal_;
    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
    AscendC::LocalTensor<float> sumLocal_;
};

// =========================================================================
// Shared dtype-dispatch helper
// =========================================================================

template <template <typename> class Kernel, typename... ExtraArgs>
__aicore__ inline void DispatchSum(
    GM_ADDR x, GM_ADDR y,
    int32_t outerTotal, int32_t redSize, int32_t blockLines,
    int32_t usedCoreNum, int32_t tasksPerCore,
    int64_t dtypeFlag, ExtraArgs... extraArgs)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(x, y, outerTotal, redSize, blockLines, usedCoreNum, tasksPerCore, extraArgs...);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(x, y, outerTotal, redSize, blockLines, usedCoreNum, tasksPerCore, extraArgs...);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(x, y, outerTotal, redSize, blockLines, usedCoreNum, tasksPerCore, extraArgs...);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry points
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void sum_merge_n(
    GM_ADDR x, GM_ADDR y,
    int32_t outerTotal, int32_t redSize, int32_t blockLines,
    int32_t usedCoreNum, int32_t tasksPerCore, int32_t rowFactor,
    int64_t dtypeFlag)
{
    DispatchSum<SumMergeNKernel>(
        x, y, outerTotal, redSize, blockLines, usedCoreNum, tasksPerCore,
        dtypeFlag, rowFactor);
}

extern "C" __global__ __aicore__ void sum_single_line(
    GM_ADDR x, GM_ADDR y,
    int32_t outerTotal, int32_t redSize, int32_t blockLines,
    int32_t usedCoreNum, int32_t tasksPerCore,
    int64_t dtypeFlag)
{
    DispatchSum<SumSingleLineKernel>(
        x, y, outerTotal, redSize, blockLines, usedCoreNum, tasksPerCore,
        dtypeFlag);
}

extern "C" __global__ __aicore__ void sum_split_line(
    GM_ADDR x, GM_ADDR y,
    int32_t outerTotal, int32_t redSize, int32_t blockLines,
    int32_t usedCoreNum, int32_t tasksPerCore,
    int64_t dtypeFlag)
{
    DispatchSum<SumSplitLineKernel>(
        x, y, outerTotal, redSize, blockLines, usedCoreNum, tasksPerCore,
        dtypeFlag);
}
