// Sum op_host — tiling calculation + strategy dispatch + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_sum_merge_n.h"
#include "aclrtlaunch_sum_single_line.h"
#include "aclrtlaunch_sum_split_line.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_LINES = 64;
constexpr int32_t DEFAULT_ROW_FACTOR = 8;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

at::Tensor sum(
    const at::Tensor &x,
    int64_t dim,
    int64_t keepdim_flag)
{
    bool keepdim = (keepdim_flag != 0);
    int32_t ndim = static_cast<int32_t>(x.dim());
    int32_t dim_int = static_cast<int32_t>(dim);

    TORCH_CHECK(ndim >= 1, "x must have at least 1 dimension");
    TORCH_CHECK(dim_int >= 0 && dim_int < ndim, "dim out of range");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
            x.scalar_type() == at::kBFloat16,
        "x must be float16, float32, or bfloat16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    // Determine if x has been pre-reshaped by the caller (reduction dim is last).
    // We trust that model_new_ascendc.py has already permuted x so that the
    // reduction dimension is the last dimension, and has reshaped to 2D:
    //   x shape = (outerTotal, redSize)
    TORCH_CHECK(ndim == 2,
        "host expects 2D input (outer_total, red_size); call from model_new_ascendc.py only");

    int32_t outerTotal = static_cast<int32_t>(x.sizes()[0]);
    int32_t redSize = static_cast<int32_t>(x.sizes()[1]);

    // Block decomposition
    int32_t lineBlocks = (outerTotal + DEFAULT_BLOCK_LINES - 1) / DEFAULT_BLOCK_LINES;
    if (lineBlocks < 1) lineBlocks = 1;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, lineBlocks));
    int32_t tasksPerCore = (lineBlocks + usedCoreNum - 1) / usedCoreNum;

    // Allocate output
    at::Tensor y = at::empty({outerTotal}, x.options());

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t blockLines = DEFAULT_BLOCK_LINES;
    int32_t rowFactor = DEFAULT_ROW_FACTOR;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // Strategy dispatch
    if (redSize <= 1024) {
        EXEC_KERNEL_CMD(sum_merge_n, blockDim,
                        x, y,
                        outerTotal, redSize, blockLines, usedCoreNum, tasksPerCore, rowFactor,
                        dtypeFlag);
    } else if (redSize > 8192) {
        EXEC_KERNEL_CMD(sum_split_line, blockDim,
                        x, y,
                        outerTotal, redSize, blockLines, usedCoreNum, tasksPerCore,
                        dtypeFlag);
    } else {
        EXEC_KERNEL_CMD(sum_single_line, blockDim,
                        x, y,
                        outerTotal, redSize, blockLines, usedCoreNum, tasksPerCore,
                        dtypeFlag);
    }

    return y;
}

}  // namespace ascend_kernel
