107	template <typename dataType>
108	class SumMergeNKernel {
109	public:
110	    __aicore__ inline void Init(
111	        GM_ADDR x, GM_ADDR y,
112	        int32_t outerTotal, int32_t redSize, int32_t blockLines,
113	        int32_t usedCoreNum, int32_t tasksPerCore, int32_t rowFactor)
114	    {
115	        this->outerTotal = outerTotal;
116	        this->redSize = redSize;
117	        this->blockLines = blockLines;
118	        this->usedCoreNum = usedCoreNum;
119	        this->tasksPerCore = tasksPerCore;
120	        this->rowFactor = rowFactor;
121	
122	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x),
123	                             static_cast<uint64_t>(outerTotal) * redSize);
124	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), outerTotal);
125	
126	        if ASCEND_IS_AIV { InitAivBuffers(); }
127	    }
128	
129	    __aicore__ inline void InitAivBuffers()
130	    {
131	        subBlockLines_ = blockLines / AscendC::GetSubBlockNum();
132	        rowLoops_ = subBlockLines_ / rowFactor;
133	
134	        pipe.InitBuffer(xInQueue_, BUFFER_NUM, kMergeRowFactor * redSize * sizeof(dataType));
135	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kMergeRowFactor * sizeof(dataType));
136	        pipe.InitBuffer(reduceBuf_, 2 * kMergeRowFactor * redSize * sizeof(uint8_t));
137	        pipe.InitBuffer(sumBuf_, kMergeRowFactor * sizeof(float));
138	        pipe.InitBuffer(sumCastBuf_, kMergeRowFactor * sizeof(float));
139	        if constexpr (!std::is_same_v<dataType, float>) {
140	            pipe.InitBuffer(xCastBuf_, kMergeRowFactor * redSize * sizeof(float));
141	        }
142	    }
143	
144	    __aicore__ inline void Process()
145	    {
146	        if ASCEND_IS_AIV {
147	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
148	            const int subBlockIdx = AscendC::GetSubBlockIdx();
149	
150	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
151	                const int bx = coreIdx * tasksPerCore + localIdx;
152	                if (bx >= BlockCountHelper(outerTotal, blockLines)) {
153	                    continue;
154	                }
155	
156	                for (int r = 0; r < rowLoops_; ++r) {
157	                    const int lineBase = bx * blockLines + subBlockIdx * subBlockLines_ + r * rowFactor;
158	                    const int validLines = outerTotal - lineBase;
159	                    if (validLines > 0) {
160	                        const int rows = (validLines >= kMergeRowFactor) ? kMergeRowFactor : validLines;
161	                        ProcessRows(lineBase, rows);
162	                    }
163	                }
164	            }
165	        }
166	    }
167	
168	private:
169	    static constexpr int kMergeRowFactor = 8;
170	
171	    __aicore__ inline void CopyInX(int32_t lineBase, int32_t rows)
172	    {
173	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
174	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(lineBase) * redSize],
175	                   static_cast<uint32_t>(rows * redSize));
176	        xInQueue_.EnQue(xInLocal_);
177	    }
178	
179	    __aicore__ inline void CopyOutY(int32_t lineBase, int32_t rows)
180	    {
181	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
182	        StoreUbToGm(yGM_[lineBase], yOutLocal_, static_cast<uint32_t>(rows));
183	        yOutQueue_.FreeTensor(yOutLocal_);
184	    }
185	
186	    __aicore__ inline void ComputeRows(int32_t rows, int32_t tileSize)
187	    {
188	        const uint32_t reduceShape[2] = {
189	            static_cast<uint32_t>(rows),
190	            static_cast<uint32_t>(redSize),
191	        };
192	
193	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
194	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
195	        sumLocal_ = sumBuf_.Get<float>();
196	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, sumCastBuf_);
197	
198	        xInLocal_ = xInQueue_.DeQue<dataType>();
199	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, tileSize);
200	
201	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
202	            sumLocal_, xLocal_, reduceTmpLocal_, reduceShape, true);
203	
204	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, sumLocal_, rows);
205	
206	        xInQueue_.FreeTensor(xInLocal_);
207	        yOutQueue_.EnQue(yOutLocal_);
208	    }
209	
210	    __aicore__ inline void ProcessSingleRow(int32_t rowIdx)
211	    {
212	        const uint32_t reduceShape[2] = {1U, static_cast<uint32_t>(redSize)};
213	
214	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
215	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
216	        sumLocal_ = sumBuf_.Get<float>();
217	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, sumCastBuf_);
218	
219	        xInLocal_ = xInQueue_.DeQue<dataType>();
220	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, redSize);
221	
222	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
223	            sumLocal_, xLocal_, reduceTmpLocal_, reduceShape, true);
224	
225	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, sumLocal_, 1);
226	
227	        xInQueue_.FreeTensor(xInLocal_);
228	        yOutQueue_.EnQue(yOutLocal_);
229	        CopyOutY(rowIdx, 1);
230	    }
231	
232	    __aicore__ inline void ProcessRows(int32_t lineBase, int32_t rows)
233	    {
234	        if (rows < kMergeRowFactor) {
235	            for (int r = 0; r < rows; ++r) {
236	                CopyInX(lineBase + r, 1);
237	                ProcessSingleRow(lineBase + r);
238	            }
239	            return;
240	        }
241	
242	        const int tileSize = kMergeRowFactor * redSize;
243	        CopyInX(lineBase, kMergeRowFactor);
244	        ComputeRows(kMergeRowFactor, tileSize);
245	        CopyOutY(lineBase, kMergeRowFactor);
246	    }
