// AscendC Sum kernel — strategies: merge_n, single_line, split_line
// All strategies use simple single-row ReduceSum for reliability.
// Supports float32, float16, bfloat16.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

__aicore__ inline int32_t BlockCountHelper(int32_t M, int32_t blockM)
{
    if (blockM == 0) { return 0; }
    return (M + blockM - 1) / blockM;
}

template <typename T>
__aicore__ inline void CastInputToFloat(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void StoreFloatOutput(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        // Copy float result into output buffer from sum buffer
        uint16_t blkLen = static_cast<uint16_t>(static_cast<uint32_t>(count) * static_cast<uint32_t>(sizeof(float)));
        AscendC::DataCopyParams copyParams{static_cast<uint16_t>(1U), blkLen, static_cast<uint16_t>(0U), static_cast<uint16_t>(0U)};
        AscendC::DataCopy(out, src, copyParams);
    } else {
        AscendC::Cast(out, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// Base helper: single-row ReduceSum processing
// =========================================================================

template <typename dataType>
class SumKernelBase {
public:
    __aicore__ inline void SetGlobals(
        GM_ADDR x, GM_ADDR y, int32_t outerTotal, int32_t redSize)
    {
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x),
                             static_cast<uint64_t>(outerTotal) * redSize);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), outerTotal);
    }

protected:
    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;
};

// =========================================================================
// Strategy 1: merge_n — single-row processing via scalar ReduceSum
// =========================================================================

template <typename dataType>
class SumMergeNKernel : public SumKernelBase<dataType> {
    using Base = SumKernelBase<dataType>;
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t outerTotal, int32_t redSize, int32_t blockLines,
        int32_t usedCoreNum, int32_t tasksPerCore, int32_t rowFactor)
    {
        this->outerTotal_ = outerTotal;
        this->redSize_ = redSize;
        this->blockLines_ = blockLines;
        this->usedCoreNum_ = usedCoreNum;
        this->tasksPerCore_ = tasksPerCore;
        Base::SetGlobals(x, y, outerTotal, redSize);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        int subBlockSize = blockLines_ / AscendC::GetSubBlockNum();
        subBlockRows_ = subBlockSize;

        this->pipe.InitBuffer(xInQueue_, BUFFER_NUM, redSize_ * sizeof(dataType));
        this->pipe.InitBuffer(yOutQueue_, BUFFER_NUM, sizeof(dataType));
        this->pipe.InitBuffer(reduceBuf_, redSize_ * sizeof(float));
        this->pipe.InitBuffer(sumBuf_, sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            this->pipe.InitBuffer(xCastBuf_, redSize_ * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                const int bx = coreIdx * tasksPerCore_ + localIdx;
                if (bx >= BlockCountHelper(outerTotal_, blockLines_)) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockLines_ + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < outerTotal_) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void CopyInX(int32_t rowIdx)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_,
                   this->xGM_[static_cast<uint64_t>(rowIdx) * redSize_],
                   static_cast<uint32_t>(redSize_));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t rowIdx)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(this->yGM_[rowIdx], yOutLocal_, 1);
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void ComputeRow()
    {
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        reduceLocal_ = reduceBuf_.Get<float>();
        sumLocal_ = sumBuf_.Get<float>();

        xInLocal_ = xInQueue_.DeQue<dataType>();
        CastInputToFloat<dataType>(xLocal_, xInLocal_, xCastBuf_, redSize_);

        AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceLocal_, redSize_);

        StoreFloatOutput<dataType>(yOutLocal_, sumLocal_, xCastBuf_, 1);

        xInQueue_.FreeTensor(xInLocal_);
        yOutQueue_.EnQue(yOutLocal_);
    }

    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        CopyInX(rowIdx);
        ComputeRow();
        CopyOutY(rowIdx);
    }

private:
    int32_t outerTotal_ = 0;
    int32_t redSize_ = 0;
    int32_t blockLines_ = 0;
    int32_t usedCoreNum_ = 0;
    int32_t tasksPerCore_ = 0;
    int subBlockRows_ = 0;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> reduceLocal_;
    AscendC::LocalTensor<float> sumLocal_;
};

// =========================================================================
// Strategy 2: single_line — same as merge_n, for medium red_size
// =========================================================================

template <typename dataType>
class SumSingleLineKernel : public SumKernelBase<dataType> {
    using Base = SumKernelBase<dataType>;
public:
    __aicore__ inline void Init(
