        reduceLocal_ = reduceBuf_.Get<float>();
        sumLocal_ = sumBuf_.Get<float>();

        xInLocal_ = xInQueue_.DeQue<dataType>();
        CastInputToFloat<dataType>(xLocal_, xInLocal_, xCastBuf_, redSize_);

        AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceLocal_, redSize_);

        StoreFloatOutput<dataType>(yOutLocal_, sumLocal_, xCastBuf_, 1);

        xInQueue_.FreeTensor(xInLocal_);
        yOutQueue_.EnQue(yOutLocal_);
