// =========================================================================
// Strategy 3: split_line — tiles along reduction dimension
// =========================================================================

template <typename dataType>
class SumSplitLineKernel : public SumKernelBase<dataType> {
    using Base = SumKernelBase<dataType>;
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t outerTotal, int32_t redSize, int32_t blockLines,
        int32_t usedCoreNum, int32_t tasksPerCore)
    {
        this->outerTotal_ = outerTotal;
        this->redSize_ = redSize;
        this->blockLines_ = blockLines;
        this->usedCoreNum_ = usedCoreNum;
        this->tasksPerCore_ = tasksPerCore;
        Base::SetGlobals(x, y, outerTotal, redSize);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockRows_ = blockLines_ / AscendC::GetSubBlockNum();

        this->pipe.InitBuffer(xInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
        this->pipe.InitBuffer(yOutQueue_, BUFFER_NUM, sizeof(dataType));
        this->pipe.InitBuffer(reduceBuf_, kBlockN * sizeof(float));
        this->pipe.InitBuffer(sumBuf_, sizeof(float));
        this->pipe.InitBuffer(accBuf_, sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            this->pipe.InitBuffer(xCastBuf_, kBlockN * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                const int bx = coreIdx * tasksPerCore_ + localIdx;
                if (bx >= BlockCountHelper(outerTotal_, blockLines_)) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockLines_ + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < outerTotal_) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    static constexpr int kBlockN = 1024;

    __aicore__ inline int32_t NumTiles() const
    {
        return (redSize_ + kBlockN - 1) / kBlockN;
    }

    __aicore__ inline int32_t GetValidN(int32_t colBase) const
    {
        return (colBase + kBlockN <= redSize_) ? kBlockN : (redSize_ - colBase);
    }

    __aicore__ inline void CopyInX(int32_t rowIdx, int32_t colBase, int32_t validN)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_,
                   this->xGM_[static_cast<uint64_t>(rowIdx) * redSize_ + colBase],
                   static_cast<uint32_t>(validN));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t rowIdx)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(this->yGM_[rowIdx], yOutLocal_, 1);
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        float total = 0.0f;
        int numTiles = NumTiles();

        for (int by = 0; by < numTiles; ++by) {
            const int colBase = by * kBlockN;
            const int validN = GetValidN(colBase);

            CopyInX(rowIdx, colBase, validN);

            reduceLocal_ = reduceBuf_.Get<float>();
            sumLocal_ = sumBuf_.Get<float>();

            xInLocal_ = xInQueue_.DeQue<dataType>();
            CastInputToFloat<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);

            AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceLocal_, validN);
            total += sumLocal_.GetValue(0);

            xInQueue_.FreeTensor(xInLocal_);
        }

        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
        accLocal_ = accBuf_.Get<float>();
        AscendC::Duplicate(accLocal_, total, 1);

        // Output: copy float total to typed output
        if constexpr (std::is_same_v<dataType, float>) {
            uint16_t blkLen = static_cast<uint16_t>(sizeof(float));
            AscendC::DataCopyParams cp{static_cast<uint16_t>(1U), blkLen,
                                       static_cast<uint16_t>(0U), static_cast<uint16_t>(0U)};
            AscendC::DataCopy(yOutLocal_, accLocal_, cp);
        } else {
            AscendC::Cast(yOutLocal_, accLocal_, AscendC::RoundMode::CAST_NONE, 1);
            AscendC::PipeBarrier<PIPE_V>();
        }

        yOutQueue_.EnQue(yOutLocal_);
        CopyOutY(rowIdx);
    }

private:
    int32_t outerTotal_ = 0;
    int32_t redSize_ = 0;
    int32_t blockLines_ = 0;
    int32_t usedCoreNum_ = 0;
    int32_t tasksPerCore_ = 0;
    int subBlockRows_ = 0;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> reduceLocal_;
    AscendC::LocalTensor<float> sumLocal_;
    AscendC::LocalTensor<float> accLocal_;
};

