template <template <typename> class Kernel, typename... ExtraArgs>
__aicore__ inline void DispatchSum(
    GM_ADDR x, GM_ADDR y,
    int32_t outerTotal, int32_t redSize, int32_t blockLines,
    int32_t usedCoreNum, int32_t tasksPerCore,
    int64_t dtypeFlag, ExtraArgs... extraArgs)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(x, y, outerTotal, redSize, blockLines, usedCoreNum, tasksPerCore, extraArgs...);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(x, y, outerTotal, redSize, blockLines, usedCoreNum, tasksPerCore, extraArgs...);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(x, y, outerTotal, redSize, blockLines, usedCoreNum, tasksPerCore, extraArgs...);
        kernel.Process();
    }
}

